'use server'

import { revalidatePath } from 'next/cache'

// Simulate a simple in-memory storage (in a real app, use a database)
const userPreferences = new Map<string, boolean>()

export async function toggleNotificationPreference() {
  // In a real app, you'd get the user ID from session/auth
  const userId = 'user-1'

  // Get current preference (default to false if not set)
  const currentPreference = userPreferences.get(userId) ?? false

  // Toggle the preference
  const newPreference = !currentPreference
  userPreferences.set(userId, newPreference)

  // Simulate a small delay (like a database operation)
  await new Promise(resolve => setTimeout(resolve, 100))

  // Revalidate the current path to refresh the page
  revalidatePath('/')

  return newPreference
}

export async function getNotificationPreference() {
  // In a real app, you'd get the user ID from session/auth
  const userId = 'user-1'

  return userPreferences.get(userId) ?? false
}

